import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

public class EqualsDemo {

    /** Broken: hashCode depends on a generated id that is null until persist. */
    static class IdBased {
        Long id; final String sku;
        IdBased(String sku) { this.sku = sku; }
        @Override public boolean equals(Object o) {
            return o instanceof IdBased other && id != null && id.equals(other.id);
        }
        @Override public int hashCode() { return Objects.hashCode(id); }
    }

    /** Recommended when a natural key exists: immutable business key. */
    static class NaturalKey {
        Long id; final String sku;
        NaturalKey(String sku) { this.sku = sku; }
        @Override public boolean equals(Object o) {
            return o instanceof NaturalKey other && sku.equals(other.sku);
        }
        @Override public int hashCode() { return sku.hashCode(); }
    }

    /** Recommended otherwise: equal when ids are equal and non-null, constant hash per class. */
    static class StableHash {
        Long id;
        @Override public boolean equals(Object o) {
            return this == o || o instanceof StableHash other && id != null && id.equals(other.id);
        }
        @Override public int hashCode() { return StableHash.class.hashCode(); }
    }

    public static void main(String[] args) {
        Set<IdBased> a = new HashSet<>();
        IdBased x = new IdBased("A-1");
        a.add(x);
        x.id = 42L;                                   // "persist" assigns the id
        System.out.println("IdBased   contains after persist: " + a.contains(x));

        Set<NaturalKey> b = new HashSet<>();
        NaturalKey y = new NaturalKey("A-1");
        b.add(y);
        y.id = 42L;
        System.out.println("NaturalKey contains after persist: " + b.contains(y));

        Set<StableHash> c = new HashSet<>();
        StableHash z = new StableHash();
        c.add(z);
        z.id = 42L;
        System.out.println("StableHash contains after persist: " + c.contains(z));
        StableHash copy = new StableHash();
        copy.id = 42L;                                // detached copy of the same row
        System.out.println("StableHash detached copy equals: " + z.equals(copy));
    }
}

