package com.example.shop.service;

import com.example.shop.domain.Customer;
import com.example.shop.domain.PurchaseOrder;
import com.example.shop.repo.CustomerRepository;
import com.example.shop.repo.PurchaseOrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    private final CustomerRepository customers;
    private final PurchaseOrderRepository orders;

    public OrderService(CustomerRepository customers, PurchaseOrderRepository orders) {
        this.customers = customers;
        this.orders = orders;
    }
    @Transactional
    public Long place(long customerId, String sku, int qty) {
        Customer customer = customers.getReferenceById(customerId);   // proxy, no SQL
        PurchaseOrder order = new PurchaseOrder(customer);
        order.addLine(sku, qty);
        return orders.save(order).getId();                            // persist, cascades to lines
    }

    @Transactional
    public void pay(long orderId) {
        PurchaseOrder order = orders.findById(orderId).orElseThrow();
        order.markPaid();                                             // no save() call needed
    }
}

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

public class MiniContext {

    interface Customer { long id(); String name(); }

    /** The "database": a map of rows; every access prints the SQL a provider would send. */
    static class Db {
        final Map<Long, String[]> rows = new HashMap<>();
        String[] select(long id) {
            System.out.println("  SQL> select id, name, tier from customer where id = " + id);
            return rows.get(id);
        }
        void update(long id, String sql) {
            System.out.println("  SQL> " + sql + " where id = " + id);
        }
    }

    static class CustomerEntity {
        long id; String name; String tier;
        CustomerEntity(long id, String name, String tier) {
            this.id = id; this.name = name; this.tier = tier;
        }
    }

    /** Minimal persistence context: identity map, snapshots, dirty checking on flush. */
    static class Context {
        final Db db;
        final Map<Long, CustomerEntity> managed = new LinkedHashMap<>();
        final Map<Long, String[]> snapshot = new HashMap<>();
        Context(Db db) { this.db = db; }

        CustomerEntity find(long id) {
            CustomerEntity e = managed.get(id);
            if (e != null) {
                System.out.println("  (first-level cache hit for id " + id + ")");
                return e;
            }
            String[] r = db.select(id);
            if (r == null) return null;
            e = new CustomerEntity(id, r[0], r[1]);
            managed.put(id, e);
            snapshot.put(id, r.clone());
            return e;
        }

        Customer getReference(long id) {      // lazy proxy: no SQL until a method is called
            InvocationHandler h = new InvocationHandler() {
                CustomerEntity target;
                public Object invoke(Object p, java.lang.reflect.Method m, Object[] a) {
                    if (m.getName().equals("id")) return id;      // identifier needs no SQL
                    if (target == null) target = find(id);
                    return m.getName().equals("name") ? target.name : null;
                }
            };
            return (Customer) Proxy.newProxyInstance(Customer.class.getClassLoader(),
                    new Class<?>[] {Customer.class}, h);
        }
        void flush() {
            System.out.println("  flush: comparing " + managed.size() + " managed instance(s)");
            for (CustomerEntity e : managed.values()) {
                String[] old = snapshot.get(e.id);
                boolean dirty = !Objects.equals(old[0], e.name) || !Objects.equals(old[1], e.tier);
                if (dirty) {   // like Hibernate's default, every column is written
                    db.update(e.id, "update customer set name = '" + e.name
                            + "', tier = '" + e.tier + "'");
                    snapshot.put(e.id, new String[] {e.name, e.tier});
                }
            }
        }
        void detach(CustomerEntity e) { managed.remove(e.id); snapshot.remove(e.id); }
    }

    public static void main(String[] args) {
        Db db = new Db();
        db.rows.put(1L, new String[] {"Asha", "SILVER"});
        db.rows.put(2L, new String[] {"Ravi", "GOLD"});
        Context ctx = new Context(db);

        System.out.println("1. find(1) twice:");
        CustomerEntity a = ctx.find(1), b = ctx.find(1);
        System.out.println("  same instance: " + (a == b));

        System.out.println("2. change a field, no explicit save, then flush:");
        a.tier = "GOLD";
        ctx.flush();
        System.out.println("  flush again (nothing changed):");
        ctx.flush();

        System.out.println("3. getReference(2) is a proxy:");
        Customer ref = ctx.getReference(2);
        System.out.println("  id() = " + ref.id() + " (no SQL)");
        System.out.println("  name() = " + ref.name());

        System.out.println("4. detached entity is no longer tracked:");
        ctx.detach(a);
        a.name = "Asha K";
        ctx.flush();
        System.out.println("  (no UPDATE was emitted for the detached instance)");
    }
}

