package com.example.shop.service;

import com.example.shop.domain.Product;
import com.example.shop.repo.ProductRepository;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class StockService {

    private static final int MAX_ATTEMPTS = 3;

    private final ProductRepository products;
    private final TransactionTemplate tx;

    public StockService(ProductRepository products, TransactionTemplate tx) {
        this.products = products;
        this.tx = tx;
    }

    public void reserve(long productId, int qty) {
        for (int attempt = 1; ; attempt++) {
            try {
                tx.executeWithoutResult(status -> {          // one new transaction per attempt
                    Product p = products.findById(productId).orElseThrow();
                    p.decrease(qty);                         // throws when stock would be negative
                });
                return;
            } catch (ObjectOptimisticLockingFailureException e) {
                if (attempt == MAX_ATTEMPTS) throw e;        // surface as 409 or 503
            }
        }
    }
}

