import org.springframework.data.jpa.repository.EntityGraph;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PurchaseOrderRepository extends JpaRepository<PurchaseOrder, Long> {

    /** Step 1: paginate identifiers only; no collection is joined, so LIMIT is applied in SQL. */
    @Query(value = "select o.id from PurchaseOrder o where o.status = :status "
            + "order by o.createdAt desc, o.id",
           countQuery = "select count(o) from PurchaseOrder o where o.status = :status")
    Page<Long> findIdsByStatus(@Param("status") Status status, Pageable pageable);

    /** Step 2: load the aggregates of exactly those identifiers with one join. */
    @Query("select o from PurchaseOrder o join fetch o.customer left join fetch o.lines "
            + "where o.id in :ids order by o.createdAt desc, o.id")
    List<PurchaseOrder> findWithLinesByIdIn(@Param("ids") Collection<Long> ids);

    /** To-one data only: join fetch is safe with pagination; Slice avoids the count query. */
    @EntityGraph(attributePaths = "customer")
    Slice<PurchaseOrder> findByStatus(Status status, Pageable pageable);
}

