import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderQueryService {

    private final PurchaseOrderRepository orders;

    public OrderQueryService(PurchaseOrderRepository orders) { this.orders = orders; }
    @Transactional(readOnly = true)
    public Page<OrderView> page(Status status, Pageable pageable) {
        Page<Long> ids = orders.findIdsByStatus(status, pageable);              // statements 1, 2
        List<PurchaseOrder> loaded = orders.findWithLinesByIdIn(ids.getContent()); // statement 3
        List<OrderView> views = loaded.stream().map(OrderView::of).toList();    // inside the tx
        return new PageImpl<>(views, pageable, ids.getTotalElements());
    }
}

