import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.Callable;

public class TxSim {
    enum Propagation { REQUIRED, REQUIRES_NEW, NESTED }

    static class UnexpectedRollbackException extends RuntimeException {
        UnexpectedRollbackException(String m) { super(m); }
    }

    static class AuditException extends Exception {
        AuditException(String m) { super(m); }
    }

    /** One physical transaction, i.e. one connection. */
    static class Tx {
        final int id;
        boolean rollbackOnly;
        Tx(int id) { this.id = id; }
    }

    static final Deque<Tx> STACK = new ArrayDeque<>();   // one thread only in this demo
    static int seq = 0;

    static void log(String s) { System.out.println("  ".repeat(STACK.size()) + s); }

    static <T> T execute(String name, Propagation p, Callable<T> body) throws Exception {
        Tx current = STACK.peek();
        boolean owner = current == null || p == Propagation.REQUIRES_NEW;
        boolean savepoint = !owner && p == Propagation.NESTED;
        Tx tx = owner ? new Tx(++seq) : current;
        if (owner) {
            String susp = current != null ? " (tx#" + current.id + " suspended)" : "";
            log(name + ": BEGIN tx#" + tx.id + susp);
            STACK.push(tx);
        } else {
            log(name + (savepoint ? ": SAVEPOINT in tx#" : ": joins tx#") + tx.id);
        }
        T result;
        try {
            result = body.call();
        } catch (RuntimeException | Error ex) {               // default rule: unchecked => rollback
            if (owner) {
                STACK.pop();
                log(name + ": ROLLBACK tx#" + tx.id + " (" + ex.getMessage() + ")");
            }
            else if (savepoint) log(name + ": ROLLBACK TO SAVEPOINT (" + ex.getMessage() + ")");
            else { tx.rollbackOnly = true; log(name + ": tx#" + tx.id + " marked rollback-only"); }
            throw ex;
        } catch (Exception ex) {                              // checked => commit anyway
            if (owner) {
                STACK.pop();
                log(name + ": COMMIT tx#" + tx.id + " despite " + ex.getMessage());
            }
            throw ex;
        }
        if (owner) {
            STACK.pop();
            if (tx.rollbackOnly) {
                log(name + ": ROLLBACK tx#" + tx.id + " (rollback-only)");
                throw new UnexpectedRollbackException("marked as rollback-only");
            }
            log(name + ": COMMIT tx#" + tx.id);
        }
        return result;
    }

    static Void fail(String m) { throw new IllegalStateException(m); }

    static void step(String title) { System.out.println("\n" + title); }

    public static void main(String[] args) throws Exception {
        step("A. REQUIRES_NEW commits independently of a failing outer transaction");
        try {
            execute("placeOrder", Propagation.REQUIRED, () -> {
                execute("audit", Propagation.REQUIRES_NEW, () -> {
                    log("INSERT audit_log");
                    return null;
                });
                execute("reserve", Propagation.REQUIRED, () -> {
                    log("UPDATE stock");
                    return null;
                });
                return fail("payment declined");
            });
        } catch (RuntimeException e) { System.out.println("caller sees: " + e.getMessage()); }

        step("B. NESTED: failure rolls back to the savepoint only");
        execute("placeOrder", Propagation.REQUIRED, () -> {
            try {
                execute("loyalty", Propagation.NESTED, () -> fail("points service down"));
            }
            catch (RuntimeException e) { log("placeOrder caught: " + e.getMessage()); }
            return null;
        });

        step("C. Inner REQUIRED fails, outer catches: the transaction is poisoned");
        try {
            execute("placeOrder", Propagation.REQUIRED, () -> {
                try {
                    execute("notify", Propagation.REQUIRED, () -> fail("mail server down"));
                }
                catch (RuntimeException e) { log("placeOrder caught: " + e.getMessage()); }
                return null;
            });
        } catch (UnexpectedRollbackException e) {
            System.out.println("caller sees: " + e.getMessage());
        }

        step("D. Checked exception: the default rule commits");
        try {
            execute("importFile", Propagation.REQUIRED, () -> {
                throw new AuditException("bad row 17");
            });
        } catch (AuditException e) { System.out.println("caller sees: " + e.getMessage()); }
    }
}

