import com.example.shop.repo.CustomerRepository;
import com.example.shop.repo.PurchaseOrderRepository;
import java.math.BigDecimal;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class CheckoutService {

    public record OrderPaid(long orderId) { }

    private final TransactionTemplate tx;
    private final CustomerRepository customers;
    private final PurchaseOrderRepository orders;
    private final PaymentGateway gateway;
    private final AuditService audit;
    private final ApplicationEventPublisher events;

    public CheckoutService(TransactionTemplate tx, CustomerRepository customers,
                           PurchaseOrderRepository orders, PaymentGateway gateway,
                           AuditService audit, ApplicationEventPublisher events) {
        this.tx = tx;
        this.customers = customers;
        this.orders = orders;
        this.gateway = gateway;
        this.audit = audit;
        this.events = events;
    }

    /** Not transactional: the remote call must not run while a connection is held. */
    public long checkout(long customerId, String sku, int qty, BigDecimal amount) {
        // unit 1: short transaction, connection returned to the pool at commit
        Long orderId = tx.execute(status -> {
            PurchaseOrder order = new PurchaseOrder(customers.getReferenceById(customerId));
            order.addLine(sku, qty);
            return orders.save(order).getId();
        });

        // remote call: no transaction, no connection
        boolean approved = gateway.charge(orderId, amount);

        // unit 2: short transaction recording the outcome
        tx.executeWithoutResult(status -> {
            PurchaseOrder order = orders.findById(orderId).orElseThrow();
            if (approved) {
                order.markPaid();
                events.publishEvent(new OrderPaid(orderId));      // delivered after commit
            } else {
                order.cancel();
            }
            audit.record(orderId, approved ? "PAID" : "DECLINED"); // REQUIRES_NEW
        });
        return orderId;
    }
}

