  import org.springframework.dao.ConcurrencyFailureException;

  public final class Retry {

      private Retry() { }

      public static <T> T onConcurrencyFailure(int maxAttempts, Supplier<T> unitOfWork) {
          for (int attempt = 1; ; attempt++) {
              try {
                  return unitOfWork.get();
              } catch (ConcurrencyFailureException e) {   // deadlock, serialisation, optimistic lock
                  if (attempt >= maxAttempts) throw e;
                  long backoffMs = (20L << attempt) + ThreadLocalRandom.current().nextLong(20);
                  try {
                      Thread.sleep(backoffMs);
                  } catch (InterruptedException ie) {
                      Thread.currentThread().interrupt();
                      throw e;
                  }
              }
          }
      }
  }

