import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class PoolSim {
    static final int POOL = 10, CLIENTS = 50, REQUESTS_PER_CLIENT = 20, TIMEOUT_MS = 300;

    static void run(String label, int dbMs, int remoteMs, boolean remoteInsideTx) throws Exception {
        Semaphore pool = new Semaphore(POOL, true);
        List<Long> waits = Collections.synchronizedList(new ArrayList<>());
        AtomicInteger timeouts = new AtomicInteger(), done = new AtomicInteger();
        long t0 = System.nanoTime();
        List<Thread> ts = new ArrayList<>();
        for (int c = 0; c < CLIENTS; c++) {
            ts.add(Thread.ofPlatform().start(() -> {
                for (int i = 0; i < REQUESTS_PER_CLIENT; i++) {
                    long w0 = System.nanoTime();
                    try {
                        if (!pool.tryAcquire(TIMEOUT_MS, TimeUnit.MILLISECONDS)) {
                            timeouts.incrementAndGet();
                            continue;
                        }
                        waits.add((System.nanoTime() - w0) / 1_000_000);
                        try {
                            Thread.sleep(dbMs);                      // SQL work
                            if (remoteInsideTx) Thread.sleep(remoteMs);   // still holding
                        } finally { pool.release(); }
                        if (!remoteInsideTx) Thread.sleep(remoteMs);   // after release
                        done.incrementAndGet();
                    } catch (InterruptedException e) { return; }
                }
            }));
        }
        for (Thread t : ts) t.join();
        double secs = (System.nanoTime() - t0) / 1e9;
        Collections.sort(waits);
        long p95 = waits.isEmpty() ? -1 : waits.get((int) (waits.size() * 0.95) - 1);
        System.out.printf("%-34s done=%4d timeouts=%4d  req/s=%6.1f  wait p95=%4d ms%n",
                label, done.get(), timeouts.get(), done.get() / secs, p95);
    }

    public static void main(String[] args) throws Exception {
        System.out.println("pool=" + POOL + " clients=" + CLIENTS
                + " acquire timeout=" + TIMEOUT_MS + " ms");
        run("short tx (10 ms SQL), remote after", 10, 100, false);
        run("long tx (10 ms SQL + remote 100 ms)", 10, 100, true);
    }
}

