import com.example.shop.domain.Product;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class ProductImportService {

    public record Row(String sku, String name) { }

    private static final int JDBC_BATCH = 50;       // equals hibernate.jdbc.batch_size
    private static final int CHUNK = 500;           // rows per transaction

    @PersistenceContext
    private EntityManager em;

    private final TransactionTemplate tx;

    public ProductImportService(TransactionTemplate tx) { this.tx = tx; }

    public int importAll(List<Row> rows) {
        int done = 0;
        for (int from = 0; from < rows.size(); from += CHUNK) {
            List<Row> chunk = rows.subList(from, Math.min(from + CHUNK, rows.size()));
            tx.executeWithoutResult(status -> persistChunk(chunk));
            done += chunk.size();
        }
        return done;
    }

    private void persistChunk(List<Row> chunk) {
        int i = 0;
        for (Row r : chunk) {
            em.persist(new Product(r.sku(), r.name()));
            if (++i % JDBC_BATCH == 0) {
                em.flush();          // sends one JDBC batch of 50 inserts
                em.clear();          // releases entities and snapshots
            }
        }
    }
}

