import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MiniRepo {

    interface OrderRepository {
        String findByStatus(String status);
        String findByStatusAndCustomerId(String status, long customerId);
        String findTop3ByStatusOrderByCreatedAtDesc(String status);
        String countByStatus(String status);
        String existsByCustomerId(long customerId);
    }

    static final Pattern NAME = Pattern.compile(
            "(find|count|exists)(?:Top(\\d+))?By([A-Za-z]+?)(?:OrderBy([A-Za-z]+?)(Asc|Desc))?");

    static String column(String property) {                 // createdAt -> created_at
        return property.replaceAll("([a-z])([A-Z])", "$1_$2").toLowerCase();
    }

    /** What PartTree does in Spring Data, reduced to equality predicates joined by And. */
    static String toSql(String method, Object[] args) {
        Matcher m = NAME.matcher(method);
        if (!m.matches()) {
            throw new IllegalArgumentException("Cannot derive a query from " + method);
        }
        String subject = m.group(1);
        List<String> predicates = new ArrayList<>();
        String[] parts = m.group(3).split("And");
        for (int i = 0; i < parts.length; i++) {
            Object a = args[i];
            String lit = a instanceof String ? "'" + a + "'" : String.valueOf(a);
            predicates.add(column(parts[i]) + " = " + lit);
        }
        String where = " where " + String.join(" and ", predicates);
        String select = switch (subject) {
            case "count" -> "select count(*) from purchase_order";
            case "exists" -> "select 1 from purchase_order";
            default -> "select id, customer_id, status from purchase_order";
        };
        String order = m.group(4) == null ? ""
                : " order by " + column(m.group(4)) + " " + m.group(5).toLowerCase();
        String limit = m.group(2) != null ? " limit " + m.group(2)
                : subject.equals("exists") ? " limit 1" : "";
        return select + where + order + limit + ";";
    }

    public static void main(String[] args) {
        OrderRepository repo = (OrderRepository) Proxy.newProxyInstance(
                MiniRepo.class.getClassLoader(), new Class<?>[] {OrderRepository.class},
                (proxy, method, a) -> toSql(method.getName(), a));
        System.out.println(repo.findByStatus("NEW"));
        System.out.println(repo.findByStatusAndCustomerId("SHIPPED", 7L));
        System.out.println(repo.findTop3ByStatusOrderByCreatedAtDesc("NEW"));
        System.out.println(repo.countByStatus("NEW"));
        System.out.println(repo.existsByCustomerId(7L));
    }
}

