import com.example.shop.domain.PurchaseOrder;
import com.example.shop.domain.PurchaseOrder.Status;
import jakarta.persistence.criteria.Join;
import java.time.Instant;
import org.springframework.data.jpa.domain.Specification;

public final class OrderSpecs {

    private OrderSpecs() { }

    public static Specification<PurchaseOrder> hasStatus(Status status) {
        return (root, query, cb) -> status == null ? null : cb.equal(root.get("status"), status);
    }

    public static Specification<PurchaseOrder> createdFrom(Instant from) {
        return (root, query, cb) ->
                from == null ? null : cb.greaterThanOrEqualTo(root.get("createdAt"), from);
    }

    public static Specification<PurchaseOrder> customerNameContains(String fragment) {
        return (root, query, cb) -> {
            if (fragment == null || fragment.isBlank()) return null;
            Join<Object, Object> customer = root.join("customer");
            String pattern = "%" + escapeLike(fragment.toLowerCase()) + "%";
            return cb.like(cb.lower(customer.get("name")), pattern, '\\');
        };
    }

    /** Fetch the customer for the data query only; the count query has no entity to fetch into. */
    public static Specification<PurchaseOrder> fetchCustomer() {
        return (root, query, cb) -> {
            Class<?> type = query.getResultType();
            if (type != Long.class && type != long.class) {
                root.fetch("customer");
            }
            return null;
        };
    }

    private static String escapeLike(String s) {
        return s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
    }
}

