import com.example.shop.repo.OrderSearchRepository;
import java.time.Instant;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderSearchService {

    public record OrderSummary(Long id, String status, String customer) { }

    private final OrderSearchRepository orders;

    public OrderSearchService(OrderSearchRepository orders) { this.orders = orders; }
    @Transactional(readOnly = true)
    public Page<OrderSummary> search(Status status, Instant from, String customerName,
                                     Pageable pageable) {
        Specification<PurchaseOrder> spec = Specification
                .where(hasStatus(status))
                .and(createdFrom(from))
                .and(customerNameContains(customerName))
                .and(fetchCustomer());
        return orders.findAll(spec, pageable)
                .map(o -> new OrderSummary(o.getId(), o.getStatus().name(),
                        o.getCustomer().getName()));
    }
}
